import { load, dump, YAML11_SCHEMA } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // YAML 1.1 hex integers allow an optional sign: [-+]?0x[0-9a-fA-F_]+
    assert.strictEqual(load('-0x1F', { schema: YAML11_SCHEMA }), -31);
    assert.strictEqual(load('+0x1F', { schema: YAML11_SCHEMA }), 31);
    // a non-sign character before 0x must not turn the scalar into an integer
    assert.strictEqual(load('10x1F', { schema: YAML11_SCHEMA }), '10x1F');
